'use client'

import { use } from 'react'
import { getInventory } from '@/lib/data'

export function InventoryDisplay({ inventoryPromise }: { inventoryPromise: ReturnType<typeof getInventory> }) {
  const inventory = use(inventoryPromise)

  return (
    <>
      <p>{inventory.count} in stock</p>
      <p>Price: ${inventory.price}</p>
    </>
  )
}

export default function Loading() {
  return (
    <main>
      <h1>Premium Widget</h1>
      <p>Loading inventory...</p>
    </main>
  )
}

import { Suspense } from 'react'
import { getInventory } from '@/lib/data'
import { InventoryDisplay } from './InventoryDisplay'

export default function ProductPage() {
  const inventoryPromise = getInventory()

  return (
    <main>
      <h1>Premium Widget</h1>
      <Suspense fallback={<p>Loading inventory...</p>}>
        <InventoryDisplay inventoryPromise={inventoryPromise} />
      </Suspense>
    </main>
  )
}
